<?php
// Generated by build-release.py: the console, behind the same take-down switch.
const TITLE = 'Application Console v0.2.0';
$share = basename(dirname(__DIR__));
$lib = __DIR__ . '/../../../api/shares_lib.php';
$tracked = false;
if (is_file($lib)) {
    try {
        require_once $lib;
        share_register($share, TITLE, '/sites/' . $share . '/');
        share_gate($share);
        $tracked = true;
    } catch (Throwable $e) { error_log('share tracking: ' . $e->getMessage()); }
}
function track(string $type, array $extra = []): void {
    global $share, $tracked;
    if (!$tracked) return;
    try { share_hit($share, $type, $extra); } catch (Throwable $e) { error_log('share tracking: ' . $e->getMessage()); }
}
header('Content-Type: text/html; charset=utf-8');
header('Cache-Control: no-store');
header('X-Robots-Tag: noindex, nofollow');
readfile(__DIR__ . '/console.html');
